(428434, 38367, 9441, '<td valign="top">wonderful photo...I love the mood it creates...nice natural lighting...</td>', 'wonderful photo...I love the mood it creates...nice natural lighting...', '2003-09-24 12:06:52.000000', NULL, 1),
