INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(428465, 39369, 11155, '<td valign="top">The water adds to the "rest" feeling in this image.  Beautifully done.  10 from me.</td>', 'The water adds to the "rest" feeling in this image.  Beautifully done.  10 from me.', '2003-09-24 12:19:01.000000', NULL, 1),
(428473, 39407, 9441, '<td valign="top">how original...very cute...nice lighting!</td>', 'how original...very cute...nice lighting!', '2003-09-24 12:24:41.000000', NULL, 1),
(428476, 39185, 7994, '<td valign="top">wow! where did you make this shot from?</td>', 'wow! where did you make this shot from?', '2003-09-24 12:25:57.000000', NULL, 1),
(428480, 39161, 7994, '<td valign="top">interesting idea</td>', 'interesting idea', '2003-09-24 12:28:52.000000', NULL, 1),
(428483, 38201, 11155, '<td valign="top">Attractive model, excellent expression.  Image looks a little grainy, but I feel that it might add to the feel of the image.  Nice work, good luck!</td>', 'Attractive model, excellent expression.  Image looks a little grainy, but I feel that it might add to the feel of the image.  Nice work, good luck!', '2003-09-24 12:31:41.000000', NULL, 1),
(428486, 38828, 9441, '<td valign="top">This is toooo cute!  I love it!  Great photograph....left side of the photo is slightly blurred, but it''s still a great shot!</td>', 'This is toooo cute!  I love it!  Great photograph....left side of the photo is slightly blurred, but it''s still a great shot!', '2003-09-24 12:32:42.000000', NULL, 1),
(428487, 38372, 9441, '<td valign="top">nice clarity and color</td>', 'nice clarity and color', '2003-09-24 12:32:56.000000', NULL, 1),
(428489, 39387, 6008, '<td valign="top">The photo certainly gives a feeling of being thankful for the lie down after the suggested surfing experience. One thing that did stand out a little to me was the shadow on the rocks in the background - it also looks like the shadow of an alien peeping at the sleeping surfer. It made me chuckle. I wonder if it would have been better with more sand leading up to the person and have the rocks completely cropped out or else not crop the rocks as much.</td>', 'The photo certainly gives a feeling of being thankful for the lie down after the suggested surfing experience. One thing that did stand out a little to me was the shadow on the rocks in the background - it also looks like the shadow of an alien peeping at the sleeping surfer. It made me chuckle. I wonder if it would have been better with more sand leading up to the person and have the rocks completely cropped out or else not crop the rocks as much.', '2003-09-24 12:34:36.000000', NULL, 1),
(428491, 39383, 9441, '<td valign="top">nice, clear reflection....</td>', 'nice, clear reflection....', '2003-09-24 12:36:24.000000', NULL, 1),
(428492, 39321, 9441, '<td valign="top">this makes me sad.....</td>', 'this makes me sad.....', '2003-09-24 12:36:59.000000', NULL, 1),
(428494, 39097, 7994, '<td valign="top">i like the look in the eye...</td>', 'i like the look in the eye...', '2003-09-24 12:38:04.000000', NULL, 1),
(428495, 39121, 9441, '<td valign="top">good photo...would score higher if it were a little clearer and sharper...</td>', 'good photo...would score higher if it were a little clearer and sharper...', '2003-09-24 12:38:26.000000', NULL, 1),
(428496, 39424, 9441, '<td valign="top">great colors...wonderful contrast....good clarity</td>', 'great colors...wonderful contrast....good clarity', '2003-09-24 12:39:07.000000', NULL, 1),
(428497, 38455, 6008, '<td valign="top">This has a nice dreamy soft focus, appropriate for a sleeping child. I''m not a huge fan of the background, though. All blue carpet or more red cushions maybe, or even having the child on the white blanket would have given it a more uniform feel. I realise this is a candid/snapshot and likely not posed and so there was no control over the background, but I feel it is the background in candid/snapshots that make some stand out more than others. The photograph does have a nice dreamy, peaceful feeling to it.</td>', 'This has a nice dreamy soft focus, appropriate for a sleeping child. I''m not a huge fan of the background, though. All blue carpet or more red cushions maybe, or even having the child on the white blanket would have given it a more uniform feel. I realise this is a candid/snapshot and likely not posed and so there was no control over the background, but I feel it is the background in candid/snapshots that make some stand out more than others. The photograph does have a nice dreamy, peaceful feeling to it.', '2003-09-24 12:39:14.000000', NULL, 1),
(428499, 38920, 7994, '<td valign="top">very good photo, though i think it would gain if the girl was a little closer, the whole pier is unnecessary. still 8</td>', 'very good photo, though i think it would gain if the girl was a little closer, the whole pier is unnecessary. still 8', '2003-09-24 12:39:52.000000', NULL, 1),
(428500, 39296, 7994, '<td valign="top">where did you find such a great photo? 10</td>', 'where did you find such a great photo? 10', '2003-09-24 12:40:27.000000', NULL, 1),
(428509, 39208, 6008, '<td valign="top">The glow and warm cast from the candles adds an interesting color to the image. I also like how she is partially hidden in shadow. The phrase ''burning the candle at both ends'' come to mind while I view this. I would have perhaps cropped it a little higher to get rid of the distracting tray? near the bottom left. It doesnt really add anything other than a slight distraction and the suggested crop wouldnt affect much of the girl either.</td>', 'The glow and warm cast from the candles adds an interesting color to the image. I also like how she is partially hidden in shadow. The phrase ''burning the candle at both ends'' come to mind while I view this. I would have perhaps cropped it a little higher to get rid of the distracting tray? near the bottom left. It doesnt really add anything other than a slight distraction and the suggested crop wouldnt affect much of the girl either.', '2003-09-24 12:51:35.000000', NULL, 1),
(428511, 38440, 10414, '<td valign="top">THIS is priceless!!!!!!!!!    10</td>', 'THIS is priceless!!!!!!!!!    10', '2003-09-24 12:54:35.000000', NULL, 1),
(428512, 38658, 6008, '<td valign="top">The idea is interesting, and a little spooky, but unfortunately it seems very blurry. At a guess I would say this was somewhere with very little light and the shot was taken handheld? Compositionally it also seems lacking. It would seem the focal point is the skeleton so you could afford to crop it a little more, and having the lines of the grate be straight instead of tilted could also help.</td>', 'The idea is interesting, and a little spooky, but unfortunately it seems very blurry. At a guess I would say this was somewhere with very little light and the shot was taken handheld? Compositionally it also seems lacking. It would seem the focal point is the skeleton so you could afford to crop it a little more, and having the lines of the grate be straight instead of tilted could also help.', '2003-09-24 12:55:04.000000', NULL, 1),
(428521, 39247, 6008, '<td valign="top">I''m trying to comment on the majority of the ''at rest'' images, but there isnt much I can say about this one. The dolphins are cute and I like the glow of the skin. There seems to be a little blur in places, but I''m sure that''s due to the fact that they can be quite fast creatures. I''m not a stickler for photographs being ''on topic'', but I really do not see much ''at rest'' here. The dolphin isnt sitting or laying down, and seems to be more ''at play'' than ''at rest''.</td>', 'I''m trying to comment on the majority of the ''at rest'' images, but there isnt much I can say about this one. The dolphins are cute and I like the glow of the skin. There seems to be a little blur in places, but I''m sure that''s due to the fact that they can be quite fast creatures. I''m not a stickler for photographs being ''on topic'', but I really do not see much ''at rest'' here. The dolphin isnt sitting or laying down, and seems to be more ''at play'' than ''at rest''.', '2003-09-24 13:05:39.000000', NULL, 1),
(428524, 38860, 6008, '<td valign="top">I really like the colors in this, and the neutral background is really enhanced with the hint of red of the toadstool (mushroom?). The clarity is amazing! I think the sharpness is really what makes this image, it''s very lifelike, as if I''m actually there looking at it. Not sure about an uprooted shroom showing calm, but it''s in laying down and that''s good enough for me! Wonderful image.</td>', 'I really like the colors in this, and the neutral background is really enhanced with the hint of red of the toadstool (mushroom?). The clarity is amazing! I think the sharpness is really what makes this image, it''s very lifelike, as if I''m actually there looking at it. Not sure about an uprooted shroom showing calm, but it''s in laying down and that''s good enough for me! Wonderful image.', '2003-09-24 13:10:10.000000', NULL, 1),
(428529, 38852, 10414, '<td valign="top">Beautiful!!  :)  10</td>', 'Beautiful!!  :)  10', '2003-09-24 13:11:25.000000', NULL, 1),
(428533, 38393, 10414, '<td valign="top">Ahhhhhhhhhh........:)    10</td>', 'Ahhhhhhhhhh........:)    10', '2003-09-24 13:12:43.000000', NULL, 1),
(428535, 38673, 1368, '<td valign="top">cute guy ;) I think the shot would have been much better if the green blanket would not have been there in the back</td>', 'cute guy ;) I think the shot would have been much better if the green blanket would not have been there in the back', '2003-09-24 13:14:11.000000', NULL, 1),
(428537, 39098, 6008, '<td valign="top">I think the foreground horse on the left stole the shot. What an interesting expression, I dont know if he''s laughing or angry at the camera and coming to stick a hoof in your face. The backdrop of the mountains is of course breathtaking, although shame the sky didnt come out a little more bluer. As the central horse is a little dark it''s disappointing that the other horse''s shadows fall on him/her. I think the shadows, be they very unfortunate and uncontrollable, just brings the overall appeal down a little.</td>', 'I think the foreground horse on the left stole the shot. What an interesting expression, I dont know if he''s laughing or angry at the camera and coming to stick a hoof in your face. The backdrop of the mountains is of course breathtaking, although shame the sky didnt come out a little more bluer. As the central horse is a little dark it''s disappointing that the other horse''s shadows fall on him/her. I think the shadows, be they very unfortunate and uncontrollable, just brings the overall appeal down a little.', '2003-09-24 13:15:16.000000', NULL, 1),
(428539, 38666, 11738, '<td valign="top">Beautiful candid shot.  I would never have the courage to take something like this for fear of offending onlookers.  I commend you for this.  The B&amp;W treatment really adds to this shot.  One of the best of the series.  Nice work.  Some may say that its tto dark but I find that this brings character to the image.</td>', 'Beautiful candid shot.  I would never have the courage to take something like this for fear of offending onlookers.  I commend you for this.  The B&W treatment really adds to this shot.  One of the best of the series.  Nice work.  Some may say that its tto dark but I find that this brings character to the image.', '2003-09-24 13:15:26.000000', NULL, 1),
(428541, 39370, 11738, '<td valign="top">Nice and crips but over exposed.</td>', 'Nice and crips but over exposed.', '2003-09-24 13:16:00.000000', NULL, 1),
(428542, 39223, 7938, '<td valign="top">great pic, because the size it will have a low score, a pitty</td>', 'great pic, because the size it will have a low score, a pitty', '2003-09-24 13:18:12.000000', NULL, 1),
(428543, 39225, 1368, '<td valign="top">I think you should have skipped the borders and its like there is a black thing over the picture Its a little too dark, mabey you could have cropped a bit more of the top too,  But the picture is good I like the blanket behind her I think it adds something to the space there. Good luck :)</td>', 'I think you should have skipped the borders and its like there is a black thing over the picture Its a little too dark, mabey you could have cropped a bit more of the top too,  But the picture is good I like the blanket behind her I think it adds something to the space there. Good luck :)', '2003-09-24 13:19:42.000000', NULL, 1),
(428544, 38301, 11738, '<td valign="top">This could have been more interesting if cropped or compsed diffrently.  The eye searches for either feet or the top of the head, which are both absent.  Also the items on the floor to the right of the subject are quite distracting.  Nice lighting but over exposed near the bottom and top.  I would also suggest a shirt without any words or images since people will focus on that instead of the image as a whole.</td>', 'This could have been more interesting if cropped or compsed diffrently.  The eye searches for either feet or the top of the head, which are both absent.  Also the items on the floor to the right of the subject are quite distracting.  Nice lighting but over exposed near the bottom and top.  I would also suggest a shirt without any words or images since people will focus on that instead of the image as a whole.', '2003-09-24 13:19:46.000000', NULL, 1),
(428548, 38828, 10108, '<td valign="top">Such incredible expressions these animals have!<br/>Absolutely amazing shot!</td>', 'Such incredible expressions these animals have!Absolutely amazing shot!', '2003-09-24 13:21:03.000000', NULL, 1),
(428550, 38365, 11738, '<td valign="top">Nice photo although I have a hard time understanding how this refers to At Rest.  Is she getting ready for bed by disrobing?  A title could have worked wonders here.</td>', 'Nice photo although I have a hard time understanding how this refers to At Rest.  Is she getting ready for bed by disrobing?  A title could have worked wonders here.', '2003-09-24 13:21:29.000000', NULL, 1),
(428553, 38661, 1368, '<td valign="top">He´s very cute! I think a sharper focus would do just fine here and mabey a clearer background. Good luck</td>', 'He´s very cute! I think a sharper focus would do just fine here and mabey a clearer background. Good luck', '2003-09-24 13:23:13.000000', NULL, 1),
(428555, 38674, 10414, '<td valign="top">Wow....the best picture yet!!!  I wanna be right there in that boat!  :)    10</td>', 'Wow....the best picture yet!!!  I wanna be right there in that boat!  :)    10', '2003-09-24 13:23:48.000000', NULL, 1),
(428557, 38424, 11738, '<td valign="top">This is a good crisp and clean shot.  I really appreciate the feeling of proximity to the subject.  The reflection is very nice as well.</td>', 'This is a good crisp and clean shot.  I really appreciate the feeling of proximity to the subject.  The reflection is very nice as well.', '2003-09-24 13:24:18.000000', NULL, 1),
(428559, 39082, 10414, '<td valign="top">I love this!!  How creative!!   10</td>', 'I love this!!  How creative!!   10', '2003-09-24 13:24:47.000000', NULL, 1),
(428560, 38796, 1368, '<td valign="top">Poor little thing Why is he painted like that?</td>', 'Poor little thing Why is he painted like that?', '2003-09-24 13:25:04.000000', NULL, 1),
(428563, 39334, 10414, '<td valign="top">It certainly LOOKS relaxing!!  :)   9</td>', 'It certainly LOOKS relaxing!!  :)   9', '2003-09-24 13:26:23.000000', NULL, 1),
(428564, 39398, 11738, '<td valign="top">Nice cat.  Mine is the same way.  As soon as the camera comes out, the eyes open.  Two suggestions: 1) try to have kitty lying down on something in a different colour (his/her fur colour is eaten up by the the pillows) and 2) try diminishing the harshness of the light coming in the right.  Good job</td>', 'Nice cat.  Mine is the same way.  As soon as the camera comes out, the eyes open.  Two suggestions: 1) try to have kitty lying down on something in a different colour (his/her fur colour is eaten up by the the pillows) and 2) try diminishing the harshness of the light coming in the right.  Good job', '2003-09-24 13:26:36.000000', NULL, 1),
(428567, 38732, 10643, '<td valign="top">even though the ball is still, the lines on the sand and the precarious placement of the ball atop the slope give this a VERY kinetic feeling, not a feeling of rest. I like the shot and am giving it a 7, but it''s not calm.</td>', 'even though the ball is still, the lines on the sand and the precarious placement of the ball atop the slope give this a VERY kinetic feeling, not a feeling of rest. I like the shot and am giving it a 7, but it''s not calm.', '2003-09-24 13:27:17.000000', NULL, 1),
(428569, 38756, 6008, '<td valign="top">I admit I''m not a cat person so you can completely ignore this comment! I like the expression on his/her face, it''s almost like a scowl at having to pose for the picture. There is also an interesting texture to his/her fur. I''m not a big fan of the crop as other than the face, the rest of the shot is almost hard to tell what''s there. I assume that''s a foot and a pillow? In most of these situations i find a head shot or larger body shot to be more visually appealing. However, there is an obvious personality coming from the image.</td>', 'I admit I''m not a cat person so you can completely ignore this comment! I like the expression on his/her face, it''s almost like a scowl at having to pose for the picture. There is also an interesting texture to his/her fur. I''m not a big fan of the crop as other than the face, the rest of the shot is almost hard to tell what''s there. I assume that''s a foot and a pillow? In most of these situations i find a head shot or larger body shot to be more visually appealing. However, there is an obvious personality coming from the image.', '2003-09-24 13:27:36.000000', NULL, 1),
(428573, 39204, 11738, '<td valign="top">Interesting shot.  Like the blue background: it sets off the steel of the gyroscope nicely.  String tip near the gyroscope edge seems to be out of focus and I can''t quite figure out why.  Nice framing too</td>', 'Interesting shot.  Like the blue background: it sets off the steel of the gyroscope nicely.  String tip near the gyroscope edge seems to be out of focus and I can''t quite figure out why.  Nice framing too', '2003-09-24 13:29:37.000000', NULL, 1),
(428575, 38290, 10643, '<td valign="top">the bright lighting gives this an energetic and lively feel. despite the sleeping baby, this is not a calm and restful shot.</td>', 'the bright lighting gives this an energetic and lively feel. despite the sleeping baby, this is not a calm and restful shot.', '2003-09-24 13:30:06.000000', NULL, 1),
(428580, 39177, 11738, '<td valign="top">VERY nice!  The low light works wonders in this shot.  Just dark enough so that you don''t see too much deaitl in the buildings on the other shore so that the eye can rest on the subjects and the landscape.  One of my favourites so far.  I wonder what they''re looking at...</td>', 'VERY nice!  The low light works wonders in this shot.  Just dark enough so that you don''t see too much deaitl in the buildings on the other shore so that the eye can rest on the subjects and the landscape.  One of my favourites so far.  I wonder what they''re looking at...', '2003-09-24 13:32:33.000000', NULL, 1),
(428582, 39036, 11432, '<td valign="top">Interesting lighting, I like the clouds, the water. It looks crooked.</td>', 'Interesting lighting, I like the clouds, the water. It looks crooked.', '2003-09-24 13:32:54.000000', NULL, 1),
(428585, 38791, 6008, '<td valign="top">This is a really pretty image, the sky is wonderful, and I''m partial to silhouette shots. Compositionally it is also good. Now I''m not a stickler for meeting the challenge, and there are a lot of ''outside the box'' alternatives, and certainly there is the saying of a ''sleepy hamlet'' with regards to towns, but I do really think it''s a bit of a stretch to fit this into ''at rest'' because of the ''sitting'' or ''laying'' aspect. However, outside of the challenge, this is a really good image.</td>', 'This is a really pretty image, the sky is wonderful, and I''m partial to silhouette shots. Compositionally it is also good. Now I''m not a stickler for meeting the challenge, and there are a lot of ''outside the box'' alternatives, and certainly there is the saying of a ''sleepy hamlet'' with regards to towns, but I do really think it''s a bit of a stretch to fit this into ''at rest'' because of the ''sitting'' or ''laying'' aspect. However, outside of the challenge, this is a really good image.', '2003-09-24 13:33:19.000000', NULL, 1),
(428588, 39425, 11432, '<td valign="top">I like the colors, Placement of brush and paste is good. Reflections on the top are distracting a little.</td>', 'I like the colors, Placement of brush and paste is good. Reflections on the top are distracting a little.', '2003-09-24 13:34:13.000000', NULL, 1),
(428592, 38464, 11738, '<td valign="top">Good shot.  Cat in the background see,s none too happy that your playing with its prey:)  I love how you haev put the cat directly in the background and in soft focus.  I do find however that the frame is a bit much.  You''re image already says so much.  No need to take away from it with an overly ornate frame.  I really like this one.</td>', 'Good shot.  Cat in the background see,s none too happy that your playing with its prey:)  I love how you haev put the cat directly in the background and in soft focus.  I do find however that the frame is a bit much.  You''re image already says so much.  No need to take away from it with an overly ornate frame.  I really like this one.', '2003-09-24 13:34:53.000000', NULL, 1),
(428593, 39373, 11432, '<td valign="top">Good detail, like the colors, that frisbee is in need of a rest, it looks pretty chewed up.</td>', 'Good detail, like the colors, that frisbee is in need of a rest, it looks pretty chewed up.', '2003-09-24 13:34:59.000000', NULL, 1),
(428597, 39058, 11432, '<td valign="top">Good Depth of Field, good detail, I like the expression on the face.</td>', 'Good Depth of Field, good detail, I like the expression on the face.', '2003-09-24 13:35:40.000000', NULL, 1),
(428601, 38450, 11432, '<td valign="top">Good colors.</td>', 'Good colors.', '2003-09-24 13:36:48.000000', NULL, 1),
(428603, 39334, 11432, '<td valign="top">Good detail, I like the softness of the shot.</td>', 'Good detail, I like the softness of the shot.', '2003-09-24 13:37:18.000000', NULL, 1),
(428604, 39302, 11738, '<td valign="top">LOL!  Love that chair and the title really adds to the image.</td>', 'LOL!  Love that chair and the title really adds to the image.', '2003-09-24 13:37:32.000000', NULL, 1),
(428607, 39070, 11432, '<td valign="top">Great lighting, I like the shadows.</td>', 'Great lighting, I like the shadows.', '2003-09-24 13:37:51.000000', NULL, 1),
(428608, 39321, 3898, '<td valign="top">It looks like its a little blurry. The lighting is good and the subject matter fits. I think that a different angle would help this shot also.</td>', 'It looks like its a little blurry. The lighting is good and the subject matter fits. I think that a different angle would help this shot also.', '2003-09-24 13:38:03.000000', NULL, 1),
(428610, 39210, 11432, '<td valign="top">Good shot, I know how hard it is to get animals at a zoo. Nice Depth of Field.</td>', 'Good shot, I know how hard it is to get animals at a zoo. Nice Depth of Field.', '2003-09-24 13:38:31.000000', NULL, 1),
(428613, 38855, 11432, '<td valign="top">I like the edges, makes it seem all soft and cuddly, I like how the girl in the middle is just there looking at the camera. Good detail.</td>', 'I like the edges, makes it seem all soft and cuddly, I like how the girl in the middle is just there looking at the camera. Good detail.', '2003-09-24 13:39:33.000000', NULL, 1),
