(431274, 39061, 8522, '<td valign="top">You may think this pedantic, but I don''t think your subject is placed, seated, or lying. 5</td>', 'You may think this pedantic, but I don''t think your subject is placed, seated, or lying. 5', '2003-09-26 04:08:36.000000', NULL, 1),
