(431558, 39311, 6888, '<td valign="top">this is a nice snapshot type photo, thank you for sharing</td>', 'this is a nice snapshot type photo, thank you for sharing', '2003-09-26 13:09:33.000000', NULL, 1),
(431559, 38828, 2764, '<td valign="top">This fellow made me laugh out loud - a nice break from cats - 8</td>', 'This fellow made me laugh out loud - a nice break from cats - 8', '2003-09-26 13:09:37.000000', NULL, 1),
(431560, 38918, 8816, '<td valign="top">Nice shot, the black and white works very well, especially with this particular cat!  Would be nice to see a closer crop though.  Nonetheless great job!</td>', 'Nice shot, the black and white works very well, especially with this particular cat!  Would be nice to see a closer crop though.  Nonetheless great job!', '2003-09-26 13:10:11.000000', NULL, 1);
