(431566, 38671, 6888, '<td valign="top">nice peaceful shot, colors are nice and vibrant, good job</td>', 'nice peaceful shot, colors are nice and vibrant, good job', '2003-09-26 13:12:20.000000', NULL, 1),
(431567, 39169, 6888, '<td valign="top">nicely composed, coloring is good, challenge met</td>', 'nicely composed, coloring is good, challenge met', '2003-09-26 13:13:41.000000', NULL, 1),
(431568, 39070, 6888, '<td valign="top">interesting take on the challenge, good lighting and composition</td>', 'interesting take on the challenge, good lighting and composition', '2003-09-26 13:14:14.000000', NULL, 1),
(431572, 38883, 8816, '<td valign="top">I love the concept of this shot, and the way you''ve overexposed the image.  My only quibble is the shadow from the glasses, if you had positioned the light perpendicular to the face you may have been able to eliminate that shadow!  I great shot though! Congrats!</td>', 'I love the concept of this shot, and the way you''ve overexposed the image.  My only quibble is the shadow from the glasses, if you had positioned the light perpendicular to the face you may have been able to eliminate that shadow!  I great shot though! Congrats!', '2003-09-26 13:15:38.000000', NULL, 1),
(431573, 39305, 6888, '<td valign="top">interesting take on the challenge, the composition, coloring &amp; lighting are all nicely done, a touch too dark for my tastes but an overall nice job</td>', 'interesting take on the challenge, the composition, coloring & lighting are all nicely done, a touch too dark for my tastes but an overall nice job', '2003-09-26 13:15:48.000000', NULL, 1),
(431574, 38353, 10084, '<td valign="top">Great closeup of the dog. I like how you were able to capture the texture of the snout. Very good reflections. Good depth of field keeps the composition interesting. Love the closed eye in the background. "8"</td>', 'Great closeup of the dog. I like how you were able to capture the texture of the snout. Very good reflections. Good depth of field keeps the composition interesting. Love the closed eye in the background. "8"', '2003-09-26 13:16:06.000000', NULL, 1),
(431576, 38464, 7190, '<td valign="top">It is a shame you didn''t get a clear image of the cat or the winner in this cat and mousre or atleast the complete image of the cat in the soft focus</td>', 'It is a shame you didn''t get a clear image of the cat or the winner in this cat and mousre or atleast the complete image of the cat in the soft focus', '2003-09-26 13:18:44.000000', NULL, 1),
(431587, 38729, 10084, '<td valign="top">The great shadows and reflections help to make this shot come alive. I could almost feel the texture on what the cat is sleeping on. Beautiful depth of field also makes it pop out of the shot. Great contrast. "10"</td>', 'The great shadows and reflections help to make this shot come alive. I could almost feel the texture on what the cat is sleeping on. Beautiful depth of field also makes it pop out of the shot. Great contrast. "10"', '2003-09-26 13:27:48.000000', NULL, 1),
(431608, 39311, 12521, '<td valign="top">Very nice image. She is so cute.</td>', 'Very nice image. She is so cute.', '2003-09-26 14:02:24.000000', NULL, 1),
(431617, 38630, 12452, '<td valign="top">amazing photo......the color is captivating</td>', 'amazing photo......the color is captivating', '2003-09-26 14:13:11.000000', NULL, 1),
(431619, 39378, 12061, '<td valign="top">love it!</td>', 'love it!', '2003-09-26 14:15:47.000000', NULL, 1),
(431620, 38350, 12061, '<td valign="top">very cute cat, could have been more sharp</td>', 'very cute cat, could have been more sharp', '2003-09-26 14:16:20.000000', NULL, 1),
