(432037, 39245, 10040, '<td valign="top">Nicely done.  The lighting, the contrast, the brightness are perfect.</td>', 'Nicely done.  The lighting, the contrast, the brightness are perfect.', '2003-09-26 22:33:16.000000', NULL, 1),
(432038, 39082, 10040, '<td valign="top">I like the "feel" of this photo a lot.  A different angle may have been better if it was at all possible.  What distracts me is the top left corner, and the street lamp.</td>', 'I like the "feel" of this photo a lot.  A different angle may have been better if it was at all possible.  What distracts me is the top left corner, and the street lamp.', '2003-09-26 22:36:07.000000', NULL, 1),
