INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(432148, 38852, 9441, '<td valign="top">sweet photo, clear and crisp, yet soft</td>', 'sweet photo, clear and crisp, yet soft', '2003-09-27 01:40:52.000000', NULL, 1),
(432150, 38799, 9441, '<td valign="top">interesting shot...very clear and sharp</td>', 'interesting shot...very clear and sharp', '2003-09-27 01:42:07.000000', NULL, 1),
(432151, 39098, 9441, '<td valign="top">very funny photo..I like this one alot...good rich color, nice clarity</td>', 'very funny photo..I like this one alot...good rich color, nice clarity', '2003-09-27 01:43:19.000000', NULL, 1),
(432199, 39035, 10084, '<td valign="top">Good contrast make the seated subject pop out of the picture. Love the shadows that you were able to capture in the rocks. It makes it feels that you are there. The great depth of field gives a calming effect. Would make a great postcard.</td>', 'Good contrast make the seated subject pop out of the picture. Love the shadows that you were able to capture in the rocks. It makes it feels that you are there. The great depth of field gives a calming effect. Would make a great postcard.', '2003-09-27 03:43:37.000000', NULL, 1),
(432201, 38264, 10084, '<td valign="top">The floating leaf really makes for a nice composition. The blueness of the water makes for a calming picture. It''s such a simple shot but it tells so much. "10"</td>', 'The floating leaf really makes for a nice composition. The blueness of the water makes for a calming picture. It''s such a simple shot but it tells so much. "10"', '2003-09-27 03:47:01.000000', NULL, 1),
(432216, 38625, 10084, '<td valign="top">Great composition. Great lighting gives the rock a very vivid shadow. Great details in the rock itself. Looks a bit like the moon. I like the dark background on the top it helps to make the rock pop out of the picture. The bottom black space is distracting and should be cropped.</td>', 'Great composition. Great lighting gives the rock a very vivid shadow. Great details in the rock itself. Looks a bit like the moon. I like the dark background on the top it helps to make the rock pop out of the picture. The bottom black space is distracting and should be cropped.', '2003-09-27 06:31:31.000000', NULL, 1),
(432250, 39410, 11570, '<td valign="top">Like the reflections and composition but can not quite see At Rest ?</td>', 'Like the reflections and composition but can not quite see At Rest ?', '2003-09-27 10:04:57.000000', NULL, 1),
(432251, 39341, 11570, '<td valign="top">If this was a candid - great shot.  If set up how did you get her to keep still long enough?</td>', 'If this was a candid - great shot.  If set up how did you get her to keep still long enough?', '2003-09-27 10:06:01.000000', NULL, 1),
(432253, 39377, 11570, '<td valign="top">I like the idea but I think a crop of the sky and the foreground in to a letterbox format might give it more impact</td>', 'I like the idea but I think a crop of the sky and the foreground in to a letterbox format might give it more impact', '2003-09-27 10:07:42.000000', NULL, 1),
(432255, 39313, 11570, '<td valign="top">A modern citiscape in B &amp; W gives more emphasis to the main subject but when the challenge is over I would like to see the colour original to compare my thoughts.</td>', 'A modern citiscape in B & W gives more emphasis to the main subject but when the challenge is over I would like to see the colour original to compare my thoughts.', '2003-09-27 10:08:57.000000', NULL, 1),
(432256, 38791, 11570, '<td valign="top">Symbolism very good but the whole image looks a little soft being dusk could it be a bit of camera shake?</td>', 'Symbolism very good but the whole image looks a little soft being dusk could it be a bit of camera shake?', '2003-09-27 10:10:05.000000', NULL, 1),
(432258, 39401, 11570, '<td valign="top">Just realised why this one gives me vertigo - it is upside down!</td>', 'Just realised why this one gives me vertigo - it is upside down!', '2003-09-27 10:11:41.000000', NULL, 1),
(432259, 39409, 11570, '<td valign="top">A clsssic image much used idea in the magazines etc but well set nonetheless.</td>', 'A clsssic image much used idea in the magazines etc but well set nonetheless.', '2003-09-27 10:12:32.000000', NULL, 1),
(432261, 38950, 11570, '<td valign="top">A gentle "soft" study - there is a prime point of focus on the left hand.  I think this lets the shot down as in B&amp;W any OOF areas stand out.  If overall sharpness was spot on I would have rated this far higher.</td>', 'A gentle "soft" study - there is a prime point of focus on the left hand.  I think this lets the shot down as in B&W any OOF areas stand out.  If overall sharpness was spot on I would have rated this far higher.', '2003-09-27 10:15:23.000000', NULL, 1),
(432262, 39425, 11570, '<td valign="top">Made me smile - do you take this to work "3 times a day"?</td>', 'Made me smile - do you take this to work "3 times a day"?', '2003-09-27 10:16:15.000000', NULL, 1),
(432263, 39422, 11570, '<td valign="top">Like the tight crop on the babies face but for me this is let down by the almost complete de saturation and the blue tone.</td>', 'Like the tight crop on the babies face but for me this is let down by the almost complete de saturation and the blue tone.', '2003-09-27 10:17:25.000000', NULL, 1),
(432264, 38353, 11570, '<td valign="top">This could have been in the Macro/Closeup challenge good all the same.</td>', 'This could have been in the Macro/Closeup challenge good all the same.', '2003-09-27 10:18:38.000000', NULL, 1),
(432265, 39420, 2716, '<td valign="top">Wonderfull portrait.  The curves of the model and the soft lighting makes this a very attractive photo.  Good luck in the challenge.  10.  jacko.</td>', 'Wonderfull portrait.  The curves of the model and the soft lighting makes this a very attractive photo.  Good luck in the challenge.  10.  jacko.', '2003-09-27 10:18:59.000000', NULL, 1),
(432266, 39369, 2716, '<td valign="top">Wonderfull warm colors.  The inclusion of the canoe in the foreground really makes the picture.  Goo luck.  Jacko.  9</td>', 'Wonderfull warm colors.  The inclusion of the canoe in the foreground really makes the picture.  Goo luck.  Jacko.  9', '2003-09-27 10:20:12.000000', NULL, 1),
(432267, 39248, 11570, '<td valign="top">Good "candid" but IMO the lighting is over the top for what is supposed to show Rest.</td>', 'Good "candid" but IMO the lighting is over the top for what is supposed to show Rest.', '2003-09-27 10:20:25.000000', NULL, 1),
(432268, 39388, 2716, '<td valign="top">what a simple slightly absurd (in a good way) composition.  Very intriguing.  Jacko.  9</td>', 'what a simple slightly absurd (in a good way) composition.  Very intriguing.  Jacko.  9', '2003-09-27 10:21:32.000000', NULL, 1),
(432269, 39236, 11570, '<td valign="top">Most unusual take on the subject pity there is light switch or something ont he wall above the subject- it does distract when the main subject is "small" in the frame.</td>', 'Most unusual take on the subject pity there is light switch or something ont he wall above the subject- it does distract when the main subject is "small" in the frame.', '2003-09-27 10:22:25.000000', NULL, 1),
(432270, 38852, 2716, '<td valign="top">What a wonderful portrait.   so engaging.  I love the inclusion of the plant on which she''s restign her head.  Jacko.  8</td>', 'What a wonderful portrait.   so engaging.  I love the inclusion of the plant on which she''s restign her head.  Jacko.  8', '2003-09-27 10:23:18.000000', NULL, 1),
(432271, 38264, 2716, '<td valign="top">wow!  This is wonderful.  The water almost looks waxy.  very nice and simple composition.  ONe of my favorites so far.  Jacko.  10</td>', 'wow!  This is wonderful.  The water almost looks waxy.  very nice and simple composition.  ONe of my favorites so far.  Jacko.  10', '2003-09-27 10:24:32.000000', NULL, 1),
(432273, 39355, 2716, '<td valign="top">What a different take.  I love the soft feel of the image and the slight motion blur.  the cool colors are just wild.  Good luck.  Jacko.  9</td>', 'What a different take.  I love the soft feel of the image and the slight motion blur.  the cool colors are just wild.  Good luck.  Jacko.  9', '2003-09-27 10:25:54.000000', NULL, 1),
(432275, 39391, 11570, '<td valign="top">Interesting take on the challenge I like this one.  The combination of soft and hard edges and the sharply contrasting colours are appealing.<br/> <br/>Did you do some curves editing?</td>', 'Interesting take on the challenge I like this one.  The combination of soft and hard edges and the sharply contrasting colours are appealing. Did you do some curves editing?', '2003-09-27 10:34:56.000000', NULL, 1),
(432278, 39082, 11570, '<td valign="top">When the challenge is over, I think some spot editing to remove the Red Traffic Light color and making the whole image monchrome with removing the buidlings details could create a very interesting silhouette.  The crop for framing is just about right.</td>', 'When the challenge is over, I think some spot editing to remove the Red Traffic Light color and making the whole image monchrome with removing the buidlings details could create a very interesting silhouette.  The crop for framing is just about right.', '2003-09-27 10:38:14.000000', NULL, 1),
