(433380, 38674, 10402, '<td valign="top">The docked boat in the foreground with the silhouetted trees in the background works well here. The reflected sun adds interest, but the image seems too dark for the time of day. This would have been a great photo with sunset/sunrise colors in the sky.</td>', 'The docked boat in the foreground with the silhouetted trees in the background works well here. The reflected sun adds interest, but the image seems too dark for the time of day. This would have been a great photo with sunset/sunrise colors in the sky.', '2003-09-28 23:11:58.000000', NULL, 1),
(433384, 39059, 12402, '<td valign="top">You captured the textures quite well. Hairs are precise. Source lighting works well.</td>', 'You captured the textures quite well. Hairs are precise. Source lighting works well.', '2003-09-28 23:16:05.000000', NULL, 1),
