(433499, 38301, 9893, '<td valign="top">Cool shirt... I love the green tones, though I wish the face weren''t covered up.</td>', 'Cool shirt... I love the green tones, though I wish the face weren''t covered up.', '2003-09-29 01:23:28.000000', NULL, 1),
(433525, 39355, 8891, '<td valign="top">Like the shot except for the motion in the arms. Like the monotone as well. BUT, is the model resting? She(???) looks like she is the throws of either an orgasm or cardiac (sic) arrest.</td>', 'Like the shot except for the motion in the arms. Like the monotone as well. BUT, is the model resting? She(???) looks like she is the throws of either an orgasm or cardiac (sic) arrest.', '2003-09-29 01:35:04.000000', NULL, 1),
