(434634, 39111, 4210, '<td valign="top">Good use of negative space. Very nice composition.</td>', 'Good use of negative space. Very nice composition.', '2003-09-29 19:46:59.000000', NULL, 1),
(434640, 39194, 4210, '<td valign="top">I really like the composition of this peice. The eye follows the line from the tip of her finger to the bottom right corner where her skin disappears under the blanket.</td>', 'I really like the composition of this peice. The eye follows the line from the tip of her finger to the bottom right corner where her skin disappears under the blanket.', '2003-09-29 19:47:56.000000', NULL, 1),
