(434654, 38922, 4210, '<td valign="top">Hmm... interesting dof, but I think it''s just a little too narrow. Good message though.</td>', 'Hmm... interesting dof, but I think it''s just a little too narrow. Good message though.', '2003-09-29 19:54:17.000000', NULL, 1),
(434655, 39068, 4210, '<td valign="top">Good lighting, colours, composition.</td>', 'Good lighting, colours, composition.', '2003-09-29 19:54:35.000000', NULL, 1),
(434657, 38324, 4210, '<td valign="top">I like the diagonal lines, but it would have been stronger if placed elsewhere but the dead center of the image.</td>', 'I like the diagonal lines, but it would have been stronger if placed elsewhere but the dead center of the image.', '2003-09-29 19:55:21.000000', NULL, 1),
(434659, 39177, 4210, '<td valign="top">I hate the micky d''s cup. But I suspect you couldn''t do anything about it. Great colours, composition.</td>', 'I hate the micky d''s cup. But I suspect you couldn''t do anything about it. Great colours, composition.', '2003-09-29 19:56:05.000000', NULL, 1),
(434662, 38943, 4210, '<td valign="top">Image is grainy, low quality. Composition is good. For a photo like this, I would have resized it smaller to hide the quality issues, and risk the "too small" comments.</td>', 'Image is grainy, low quality. Composition is good. For a photo like this, I would have resized it smaller to hide the quality issues, and risk the "too small" comments.', '2003-09-29 19:57:26.000000', NULL, 1),
(434663, 38993, 4210, '<td valign="top">That is soooo adorable. good use of narrow dof. Great colours, composition.</td>', 'That is soooo adorable. good use of narrow dof. Great colours, composition.', '2003-09-29 19:58:01.000000', NULL, 1),
(434664, 39388, 4210, '<td valign="top">Hmmm... too much negative space I think, and composition is lacking.</td>', 'Hmmm... too much negative space I think, and composition is lacking.', '2003-09-29 19:58:32.000000', NULL, 1),
