(434887, 38195, 6855, '<td valign="top">I love how the green in the cat''s eyes match the leaves. Very cool.  The light in the top right corner is a distraction, but otherwise great.</td>', 'I love how the green in the cat''s eyes match the leaves. Very cool.  The light in the top right corner is a distraction, but otherwise great.', '2003-09-30 00:27:24.000000', NULL, 1),
(434888, 39137, 6855, '<td valign="top">This is a great shot!  It almost looks 3-D - I love the effect and the border is nice.</td>', 'This is a great shot!  It almost looks 3-D - I love the effect and the border is nice.', '2003-09-30 00:28:07.000000', NULL, 1),
(434889, 38383, 11073, '<td valign="top">i would have liked to see the majority of the negative space off to the left - "leading" the subject.</td>', 'i would have liked to see the majority of the negative space off to the left - "leading" the subject.', '2003-09-30 00:28:08.000000', NULL, 1),
(434891, 38656, 8891, '<td valign="top">Super comp, colors and silhouettes...I''d knock off some of the right side and compensate at the top for just a suggested improvement....maybe? like it very much as just seems that the BG behind the fence on the right next to last gull distracts me a bit.</td>', 'Super comp, colors and silhouettes...I''d knock off some of the right side and compensate at the top for just a suggested improvement....maybe? like it very much as just seems that the BG behind the fence on the right next to last gull distracts me a bit.', '2003-09-30 00:29:25.000000', NULL, 1),
(434894, 39070, 6855, '<td valign="top">Very clever and original.</td>', 'Very clever and original.', '2003-09-30 00:30:47.000000', NULL, 1),
(434896, 39177, 8891, '<td valign="top">Think the background could be more saturated in this....perhaps a filter could have been used if one wasn''t. Otherwise quite nice</td>', 'Think the background could be more saturated in this....perhaps a filter could have been used if one wasn''t. Otherwise quite nice', '2003-09-30 00:33:26.000000', NULL, 1),
(434898, 39422, 10402, '<td valign="top">Beautifully done. Just enough contrast to show the facial features. The low contrast approach makes this very peaceful and the cyan toning suggests nighttime.</td>', 'Beautifully done. Just enough contrast to show the facial features. The low contrast approach makes this very peaceful and the cyan toning suggests nighttime.', '2003-09-30 00:33:34.000000', NULL, 1),
