(434902, 39317, 6855, '<td valign="top">Love this!  I hope to see it in the top 10.</td>', 'Love this!  I hope to see it in the top 10.', '2003-09-30 00:35:23.000000', NULL, 1),
(434903, 38828, 8891, '<td valign="top">hate the frame, but I love meerkats soooooo much that I''ll try to overlook it.</td>', 'hate the frame, but I love meerkats soooooo much that I''ll try to overlook it.', '2003-09-30 00:35:58.000000', NULL, 1),
(434904, 39109, 6855, '<td valign="top">As pretty as this is, I don''t feel really rested looking at it.  It''s still gorgeous though.</td>', 'As pretty as this is, I don''t feel really rested looking at it.  It''s still gorgeous though.', '2003-09-30 00:36:16.000000', NULL, 1),
(434905, 38794, 6855, '<td valign="top">Very cool!  This is really a great shot.  I love it!</td>', 'Very cool!  This is really a great shot.  I love it!', '2003-09-30 00:37:00.000000', NULL, 1),
(434907, 39236, 8891, '<td valign="top">super perspective, love the reflection</td>', 'super perspective, love the reflection', '2003-09-30 00:37:39.000000', NULL, 1),
(434908, 39072, 10402, '<td valign="top">Good lighting here, well maybe a bit bright but at least it is soft. I like the glint in the stuffed animal''s eye and the nightlight in the background.</td>', 'Good lighting here, well maybe a bit bright but at least it is soft. I like the glint in the stuffed animal''s eye and the nightlight in the background.', '2003-09-30 00:40:21.000000', NULL, 1),
