(435474, 39213, 9027, '<td valign="top">great vibrant colors. nice job.</td>', 'great vibrant colors. nice job.', '2003-09-30 14:58:29.000000', NULL, 1),
(435476, 38481, 9027, '<td valign="top">too much post production. think this would have been better had the blanket contrasted with the cat, something with less texture.  right now they blend together and the cat gets lost, not helped by the b/w and  contrast.</td>', 'too much post production. think this would have been better had the blanket contrasted with the cat, something with less texture.  right now they blend together and the cat gets lost, not helped by the b/w and  contrast.', '2003-09-30 15:01:01.000000', NULL, 1),
(435487, 39148, 2567, '<td valign="top">Thanks for the chuckle.  Nice shot.</td>', 'Thanks for the chuckle.  Nice shot.', '2003-09-30 15:29:01.000000', NULL, 1),
(435489, 39404, 2567, '<td valign="top">This is one of my favorites for this challenge.  Composition excellent.  Good luck.</td>', 'This is one of my favorites for this challenge.  Composition excellent.  Good luck.', '2003-09-30 15:33:33.000000', NULL, 1),
(435490, 39070, 2567, '<td valign="top">This is an interesting shot and one of my favorites this challenge.  Nice coloring and composition.  Good luck</td>', 'This is an interesting shot and one of my favorites this challenge.  Nice coloring and composition.  Good luck', '2003-09-30 15:34:33.000000', NULL, 1),
(435492, 39422, 11022, '<td valign="top">I love this image.  Good job.  I would change two things..first I''d mirror it to get a left to right flow and second, I''d change the color to sepia tones.  Still, I love this image.</td>', 'I love this image.  Good job.  I would change two things..first I''d mirror it to get a left to right flow and second, I''d change the color to sepia tones.  Still, I love this image.', '2003-09-30 15:48:08.000000', NULL, 1),
(435493, 39058, 11022, '<td valign="top">This is a really refreshing variance on the dog theme.  Good work and great title.</td>', 'This is a really refreshing variance on the dog theme.  Good work and great title.', '2003-09-30 15:48:53.000000', NULL, 1),
(435494, 39100, 11022, '<td valign="top">Very clever and nicely done.</td>', 'Very clever and nicely done.', '2003-09-30 15:49:27.000000', NULL, 1),
(435495, 39404, 11022, '<td valign="top">Very nice image and very well done.</td>', 'Very nice image and very well done.', '2003-09-30 15:49:56.000000', NULL, 1),
