(435548, 39369, 772, '<td valign="top">nice composition... the boat creates a nice contrast against the water and the color tones here are excellent :) = 10</td>', 'nice composition... the boat creates a nice contrast against the water and the color tones here are excellent :) = 10', '2003-09-30 17:53:53.000000', NULL, 1),
