INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(435560, 38854, 4888, '<td valign="top">What, no drool?</td>', 'What, no drool?', '2003-09-30 18:00:58.000000', NULL, 1),
(435561, 39171, 4888, '<td valign="top">The focus changes in the center physically hurt to look at.</td>', 'The focus changes in the center physically hurt to look at.', '2003-09-30 18:02:56.000000', NULL, 1),
(435562, 38229, 4888, '<td valign="top">Love the colors and DOF.</td>', 'Love the colors and DOF.', '2003-09-30 18:03:42.000000', NULL, 1),
(435563, 39301, 280, '<td valign="top">I find the red border too eye catching</td>', 'I find the red border too eye catching', '2003-09-30 18:03:56.000000', NULL, 1),
(435564, 38736, 4888, '<td valign="top">Although I have a disdain for sleeping cats, sleeping babies and old rusted vehicles in this challenge (too obvious), this one is so well executed, I have to grade it well.  If there were a way to get the top and left blacks just a bit blacker, it would greatly improve the depth of feeling.</td>', 'Although I have a disdain for sleeping cats, sleeping babies and old rusted vehicles in this challenge (too obvious), this one is so well executed, I have to grade it well.  If there were a way to get the top and left blacks just a bit blacker, it would greatly improve the depth of feeling.', '2003-09-30 18:05:34.000000', NULL, 1),
(435565, 39035, 4888, '<td valign="top">Interesting that the topic of the shot is the least defined/focused.  Was that intentional?  It''s definitely an interesting look.</td>', 'Interesting that the topic of the shot is the least defined/focused.  Was that intentional?  It''s definitely an interesting look.', '2003-09-30 18:06:34.000000', NULL, 1),
(435566, 39107, 4888, '<td valign="top">One of my favorites despite being a sleeping baby.  Techically well executed sans the big orange spot wedding ring.</td>', 'One of my favorites despite being a sleeping baby.  Techically well executed sans the big orange spot wedding ring.', '2003-09-30 18:09:35.000000', NULL, 1),
(435568, 38732, 4888, '<td valign="top">If it weren''t for that one cloud this would be a 10.  Love the shot.</td>', 'If it weren''t for that one cloud this would be a 10.  Love the shot.', '2003-09-30 18:11:59.000000', NULL, 1),
(435569, 39141, 4888, '<td valign="top">Ah, the gratuitous semi-naked woman.  But well executed.</td>', 'Ah, the gratuitous semi-naked woman.  But well executed.', '2003-09-30 18:13:04.000000', NULL, 1),
(435572, 39389, 4888, '<td valign="top">Just enough focus issues on the edges to be distracting.</td>', 'Just enough focus issues on the edges to be distracting.', '2003-09-30 18:15:20.000000', NULL, 1),
(435573, 39188, 4888, '<td valign="top">Nice image.  Not sure how it fits the challenge.</td>', 'Nice image.  Not sure how it fits the challenge.', '2003-09-30 18:16:11.000000', NULL, 1),
(435574, 39177, 4888, '<td valign="top">Remove the purse and that stupid cup and this image is fantastic.  As it is, it''s "merely" wonderful.</td>', 'Remove the purse and that stupid cup and this image is fantastic.  As it is, it''s "merely" wonderful.', '2003-09-30 18:20:20.000000', NULL, 1),
(435575, 39317, 4888, '<td valign="top">Cool shot.  I wish the hair (book?) at the bottom right hadn''t been clipped.</td>', 'Cool shot.  I wish the hair (book?) at the bottom right hadn''t been clipped.', '2003-09-30 18:22:41.000000', NULL, 1),
(435576, 39095, 4888, '<td valign="top">One of my favorites.  Good choice of B&amp;W as well as the border which further emphasizes the black lines already in the short.  I wish the vertical lines were just a bit more vertical.</td>', 'One of my favorites.  Good choice of B&W as well as the border which further emphasizes the black lines already in the short.  I wish the vertical lines were just a bit more vertical.', '2003-09-30 18:28:19.000000', NULL, 1),
(435578, 39127, 4888, '<td valign="top">The overexposure in the top left is distracting.  I think the angle on the sun hurts in that way as well as the long shadows on the dock.</td>', 'The overexposure in the top left is distracting.  I think the angle on the sun hurts in that way as well as the long shadows on the dock.', '2003-09-30 18:29:48.000000', NULL, 1),
(435579, 38855, 4888, '<td valign="top">Get rid of the laughers and make this a shot of the woman in the black coat, and I''d love it.  Those eyes look restful.  Love the out of focus ring.</td>', 'Get rid of the laughers and make this a shot of the woman in the black coat, and I''d love it.  Those eyes look restful.  Love the out of focus ring.', '2003-09-30 18:31:18.000000', NULL, 1),
(435580, 39200, 4888, '<td valign="top">Saw the cemetary shots coming.  Didn''t like them.  Except this one.  Nice angle.</td>', 'Saw the cemetary shots coming.  Didn''t like them.  Except this one.  Nice angle.', '2003-09-30 18:32:02.000000', NULL, 1),
(435582, 38719, 4888, '<td valign="top">I wish the rock weren''t cropped at all.  Just a bit lower would''ve helped.  Still a great shot, love the tones.</td>', 'I wish the rock weren''t cropped at all.  Just a bit lower would''ve helped.  Still a great shot, love the tones.', '2003-09-30 18:33:41.000000', NULL, 1),
(435584, 38765, 4888, '<td valign="top">Love the concentric circles in the water.</td>', 'Love the concentric circles in the water.', '2003-09-30 18:35:21.000000', NULL, 1),
(435585, 39326, 280, '<td valign="top">Unfortunately the shot doesnt look quite straight if you look at the left-hand side. However the seated person is well positioned (except for the post behind his head) and contrasts well with the tiles of the bath. And taken in Manchester, I think?</td>', 'Unfortunately the shot doesnt look quite straight if you look at the left-hand side. However the seated person is well positioned (except for the post behind his head) and contrasts well with the tiles of the bath. And taken in Manchester, I think?', '2003-09-30 18:36:08.000000', NULL, 1),
(435588, 39409, 4888, '<td valign="top">Why is she asleep with a FULL glass?</td>', 'Why is she asleep with a FULL glass?', '2003-09-30 18:37:20.000000', NULL, 1),
(435593, 39355, 4888, '<td valign="top">Love the motion blur.</td>', 'Love the motion blur.', '2003-09-30 18:41:19.000000', NULL, 1),
(435594, 38756, 4888, '<td valign="top">I hate pictures of pets in this challenge.  But this one has such inviting textures, I''ll have to exempt it from that bias.  Interesting way of cropping out the right ear.  Usually people do that post-production, not with scissors. :)</td>', 'I hate pictures of pets in this challenge.  But this one has such inviting textures, I''ll have to exempt it from that bias.  Interesting way of cropping out the right ear.  Usually people do that post-production, not with scissors. :)', '2003-09-30 18:43:00.000000', NULL, 1),
(435604, 39247, 4888, '<td valign="top">Doesn''t look very restful</td>', 'Doesn''t look very restful', '2003-09-30 18:50:55.000000', NULL, 1),
(435617, 39383, 10441, '<td valign="top">Clever use of reflection, nice shot.</td>', 'Clever use of reflection, nice shot.', '2003-09-30 19:06:01.000000', NULL, 1),
(435621, 38723, 10441, '<td valign="top">Nice shot, colors are good, focus is sharp.  I think a little tighter crop on the upper third of the frame would have made a better shot.</td>', 'Nice shot, colors are good, focus is sharp.  I think a little tighter crop on the upper third of the frame would have made a better shot.', '2003-09-30 19:10:05.000000', NULL, 1),
(435622, 39082, 11073, '<td valign="top">good idea and cool shot.  The only thing that I would change would be to increase the contrast a llittle bit to further darken the area on the bottom of the shot.  Right now, I can sort of make out some objects on the bottom, and the picture is kind of in limbo of being a silhouette or not.  I think that its a little distracting because my eyes are trying to make out what objects are on the bottom instead of appreciating the cool crane''s and their good composition up top.</td>', 'good idea and cool shot.  The only thing that I would change would be to increase the contrast a llittle bit to further darken the area on the bottom of the shot.  Right now, I can sort of make out some objects on the bottom, and the picture is kind of in limbo of being a silhouette or not.  I think that its a little distracting because my eyes are trying to make out what objects are on the bottom instead of appreciating the cool crane''s and their good composition up top.', '2003-09-30 19:12:06.000000', NULL, 1),
(435623, 39099, 10441, '<td valign="top">Interesting idea for the challenge.  The colors of some of the ground seems a bit off though.</td>', 'Interesting idea for the challenge.  The colors of some of the ground seems a bit off though.', '2003-09-30 19:12:13.000000', NULL, 1),
(435627, 39377, 10441, '<td valign="top">Good idea for the challenge, but in my opinion a tighter shot would have been better.</td>', 'Good idea for the challenge, but in my opinion a tighter shot would have been better.', '2003-09-30 19:13:38.000000', NULL, 1),
(435629, 38301, 10441, '<td valign="top">The green cans in this photo really detracts.  The obstruction in the foreground doesn''t help either.</td>', 'The green cans in this photo really detracts.  The obstruction in the foreground doesn''t help either.', '2003-09-30 19:14:52.000000', NULL, 1),
(435632, 38920, 10441, '<td valign="top">The fog or soft focus gives this photo some interesting qualities.  I remember seeing a seen like this here in May.</td>', 'The fog or soft focus gives this photo some interesting qualities.  I remember seeing a seen like this here in May.', '2003-09-30 19:18:28.000000', NULL, 1),
(435637, 39188, 10441, '<td valign="top">Looking at a shot like this on the golf course would''t give much of a peaceful feeling, just kidding!  Nice photo, though moving the island to one of the side "thirds" of the frame would have made this a great shot.</td>', 'Looking at a shot like this on the golf course would''t give much of a peaceful feeling, just kidding!  Nice photo, though moving the island to one of the side "thirds" of the frame would have made this a great shot.', '2003-09-30 19:21:58.000000', NULL, 1),
(435639, 39183, 10441, '<td valign="top">Nice idea for the challenge.  The foreground and left side of the frame seem a bit "hot" though.</td>', 'Nice idea for the challenge.  The foreground and left side of the frame seem a bit "hot" though.', '2003-09-30 19:23:13.000000', NULL, 1),
(435643, 39100, 10441, '<td valign="top">Clever idea for the challenge, composure (pun intended) is good.</td>', 'Clever idea for the challenge, composure (pun intended) is good.', '2003-09-30 19:25:05.000000', NULL, 1),
(435644, 38229, 10441, '<td valign="top">Definately a peaceful feeling here.  Nice shot.</td>', 'Definately a peaceful feeling here.  Nice shot.', '2003-09-30 19:25:56.000000', NULL, 1),
(435646, 39163, 10441, '<td valign="top">Good idea for the challenge, but the shot is way too pixelized.  You need to be closer to the subject.</td>', 'Good idea for the challenge, but the shot is way too pixelized.  You need to be closer to the subject.', '2003-09-30 19:27:13.000000', NULL, 1),
(435650, 39247, 11073, '<td valign="top">that''s a cool picture.  i get more of a feeling that the dolphin is jumping out into my living room than rest...but personal takes on categories is what makes things great...so i won''t factor that into my scoring.  I''m sure that it was just a spur of the moment shot, and it wouldn''t have been possible to do different, but only more negative space off to the right instead of the left would have made me score higher.  cool pic.</td>', 'that''s a cool picture.  i get more of a feeling that the dolphin is jumping out into my living room than rest...but personal takes on categories is what makes things great...so i won''t factor that into my scoring.  I''m sure that it was just a spur of the moment shot, and it wouldn''t have been possible to do different, but only more negative space off to the right instead of the left would have made me score higher.  cool pic.', '2003-09-30 19:28:56.000000', NULL, 1),
(435651, 38619, 10441, '<td valign="top">Great idea for the challenge!  If the whole of the bottle would have been brighter this would be a 10, 8 isn''t bad though.</td>', 'Great idea for the challenge!  If the whole of the bottle would have been brighter this would be a 10, 8 isn''t bad though.', '2003-09-30 19:29:01.000000', NULL, 1),
(435652, 38629, 11073, '<td valign="top">good use of soft lighting to convey the feeling.</td>', 'good use of soft lighting to convey the feeling.', '2003-09-30 19:29:33.000000', NULL, 1),
(435656, 38922, 10441, '<td valign="top">The depth of field needs to be brought more to the foreground for this photo to be more powerful, good idea though.</td>', 'The depth of field needs to be brought more to the foreground for this photo to be more powerful, good idea though.', '2003-09-30 19:31:10.000000', NULL, 1),
(435662, 38664, 12131, '<td valign="top">The fur is what makes this look cozy.</td>', 'The fur is what makes this look cozy.', '2003-09-30 19:37:01.000000', NULL, 1),
(435665, 39090, 12131, '<td valign="top">Creative!  That''s one of those ones that you kind of have to look twice to catch.  I surprised he hasn''t fallen off yet.</td>', 'Creative!  That''s one of those ones that you kind of have to look twice to catch.  I surprised he hasn''t fallen off yet.', '2003-09-30 19:38:21.000000', NULL, 1),
(435669, 39185, 12131, '<td valign="top">That bird looks outright pompous!  And that view makes me want to say, GET AWAY FROM THE LEDGE!  Nice how you got the Empire State Building in the background.</td>', 'That bird looks outright pompous!  And that view makes me want to say, GET AWAY FROM THE LEDGE!  Nice how you got the Empire State Building in the background.', '2003-09-30 19:41:30.000000', NULL, 1),
(435670, 38367, 12131, '<td valign="top">That''s sweet.  Why is she on the ground though when there is a chair behind her?</td>', 'That''s sweet.  Why is she on the ground though when there is a chair behind her?', '2003-09-30 19:42:36.000000', NULL, 1),
(435673, 38656, 12131, '<td valign="top">Uh oh, birds mounting an attack!   I love the colors in this one.  That gentle yet brilliant orange contrasted after a thick line with a prestine blue.  The birds add a great subject.  Just a thought though, the orange is rather expansive where the blue is very cut off.  Maybe even out the space between them?</td>', 'Uh oh, birds mounting an attack!   I love the colors in this one.  That gentle yet brilliant orange contrasted after a thick line with a prestine blue.  The birds add a great subject.  Just a thought though, the orange is rather expansive where the blue is very cut off.  Maybe even out the space between them?', '2003-09-30 19:45:16.000000', NULL, 1),
(435674, 39066, 12131, '<td valign="top">I get the message but I think this picture would be more effective if the boat were in the water.  Of course the title, "Flying Fish" says something slightly different.</td>', 'I get the message but I think this picture would be more effective if the boat were in the water.  Of course the title, "Flying Fish" says something slightly different.', '2003-09-30 19:46:25.000000', NULL, 1),
(435675, 39015, 12131, '<td valign="top">Oh jeez!  I hope everyone got okay out of that!  Creative use of the challenge though.  It reminds me of my cat when my cat wants me to scratch her back.  She arches just like that.</td>', 'Oh jeez!  I hope everyone got okay out of that!  Creative use of the challenge though.  It reminds me of my cat when my cat wants me to scratch her back.  She arches just like that.', '2003-09-30 19:48:01.000000', NULL, 1),
(435677, 38765, 12131, '<td valign="top">Beautiful. Love the rippels.</td>', 'Beautiful. Love the rippels.', '2003-09-30 19:50:19.000000', NULL, 1),
(435678, 38729, 12131, '<td valign="top">The clinging paw makes this picture.</td>', 'The clinging paw makes this picture.', '2003-09-30 19:51:24.000000', NULL, 1),
(435682, 39422, 12131, '<td valign="top">Creative use of color and lighing and style.  I''m guessing it''s a boy?  Sorry, old stereotype of Blue for boy and Pink for girl...</td>', 'Creative use of color and lighing and style.  I''m guessing it''s a boy?  Sorry, old stereotype of Blue for boy and Pink for girl...', '2003-09-30 19:53:21.000000', NULL, 1),
(435684, 39169, 8891, '<td valign="top">it appears staged, though it may not be. just too pressed and clean looking.</td>', 'it appears staged, though it may not be. just too pressed and clean looking.', '2003-09-30 19:54:11.000000', NULL, 1),
(435685, 38201, 12131, '<td valign="top">She reminds me of Molly Ringwald.  Nice picture, the posture, lighting and contrast in black and white are beautiful.</td>', 'She reminds me of Molly Ringwald.  Nice picture, the posture, lighting and contrast in black and white are beautiful.', '2003-09-30 19:54:25.000000', NULL, 1),
(435686, 39185, 4888, '<td valign="top">PIgeon is too out of focus, but great point of view.</td>', 'PIgeon is too out of focus, but great point of view.', '2003-09-30 19:54:35.000000', NULL, 1),
(435687, 39097, 12131, '<td valign="top">Resting and yet watchful.  I like this.</td>', 'Resting and yet watchful.  I like this.', '2003-09-30 19:55:40.000000', NULL, 1),
(435688, 39210, 12131, '<td valign="top">Very cool.  Do you work in a zoo or were you passing by?</td>', 'Very cool.  Do you work in a zoo or were you passing by?', '2003-09-30 19:57:15.000000', NULL, 1),
(435689, 39208, 12131, '<td valign="top">OOOoohhh, I know those days.  The homework so tedious and the day so long that you can''t stand it.  I like the candles but I''m guessing they are there for more than show.</td>', 'OOOoohhh, I know those days.  The homework so tedious and the day so long that you can''t stand it.  I like the candles but I''m guessing they are there for more than show.', '2003-09-30 19:58:58.000000', NULL, 1),
