(436960, 39367, 12061, '<td valign="top">there is lots of humor on this site .. but this IS a Digital Photography challenge - and part of the challenge is based on photo quality, obviously, and this picture doesn''t do justice =/</td>', 'there is lots of humor on this site .. but this IS a Digital Photography challenge - and part of the challenge is based on photo quality, obviously, and this picture doesn''t do justice =/', '2003-10-01 14:02:53.000000', NULL, 0),
